using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.JNT.JuntaDetalleArchivos;namespace GraphApi.Services.JNT.JuntaDetalleArchivos{    public class JuntaDetalleArchivosService : IJuntaDetalleArchivosService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public JuntaDetalleArchivosService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadJuntaDetalleArchivos>> GetJuntaDetalleArchivos(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM jnt.JuntaDetalleArchivos (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadJuntaDetalleArchivos>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetJuntaDetalleArchivosDynamic(            int? juntaDetalleArchivoID,            int? juntaDetalleID,            string? nombreArchivo,            string? ruta,            string? tipoArchivo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "JuntaDetalleArchivoID, JuntaDetalleID, NombreArchivo, Ruta, TipoArchivo, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM jnt.JuntaDetalleArchivos (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (juntaDetalleArchivoID.HasValue)            {                vSql.Append(" AND JuntaDetalleArchivoID = @JuntaDetalleArchivoID");                vParameters.Add("JuntaDetalleArchivoID",juntaDetalleArchivoID);            }            if (!string.IsNullOrWhiteSpace(nombreArchivo))            {                vSql.Append(" AND NombreArchivo LIKE @NombreArchivo");                vParameters.Add("NombreArchivo",$"%{nombreArchivo}%");            }            if (!string.IsNullOrWhiteSpace(ruta))            {                vSql.Append(" AND Ruta LIKE @Ruta");                vParameters.Add("Ruta",$"%{ruta}%");            }            if (!string.IsNullOrWhiteSpace(tipoArchivo))            {                vSql.Append(" AND TipoArchivo LIKE @TipoArchivo");                vParameters.Add("TipoArchivo",$"%{tipoArchivo}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadJuntaDetalleArchivos> CreateJuntaDetalleArchivos(clCreateJuntaDetalleArchivos objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO jnt.JuntaDetalleArchivos                (JuntaDetalleID, NombreArchivo, Ruta, TipoArchivo, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@JuntaDetalleID, @NombreArchivo, @Ruta, @TipoArchivo, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.JuntaDetalleID,                objInput.NombreArchivo,                objInput.Ruta,                objInput.TipoArchivo,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT JuntaDetalleArchivoID, JuntaDetalleID, NombreArchivo, Ruta, TipoArchivo, bEliminado                FROM jnt.JuntaDetalleArchivos (NOLOCK)                WHERE JuntaDetalleArchivoID = @JuntaDetalleArchivoID;";            var vReadParams = new { JuntaDetalleArchivoID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadJuntaDetalleArchivos>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el JuntaDetalleArchivo con ID {vNewId}.");            return vCreated;        }        public async Task<clReadJuntaDetalleArchivos?> UpdateJuntaDetalleArchivos(clUpdateJuntaDetalleArchivos objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("JuntaDetalleArchivoID", objInput.JuntaDetalleArchivoID);            if (objInput.JuntaDetalleID != null)            {                vSets.Add("JuntaDetalleID = @JuntaDetalleID");                vParameters.Add("JuntaDetalleID", objInput.JuntaDetalleID);            }            if (objInput.NombreArchivo is not null)            {                vSets.Add("NombreArchivo = @NombreArchivo");                vParameters.Add("NombreArchivo", objInput.NombreArchivo);            }            if (objInput.Ruta is not null)            {                vSets.Add("Ruta = @Ruta");                vParameters.Add("Ruta", objInput.Ruta);            }            if (objInput.TipoArchivo is not null)            {                vSets.Add("TipoArchivo = @TipoArchivo");                vParameters.Add("TipoArchivo", objInput.TipoArchivo);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE jnt.JuntaDetalleArchivos                SET {vSetClause}                WHERE JuntaDetalleArchivoID = @JuntaDetalleArchivoID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT JuntaDetalleArchivoID, JuntaDetalleID, NombreArchivo, Ruta, TipoArchivo, bEliminado                FROM jnt.JuntaDetalleArchivos (NOLOCK)                WHERE JuntaDetalleArchivoID = @JuntaDetalleArchivoID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadJuntaDetalleArchivos>(sSelect, new {  objInput.JuntaDetalleArchivoID });        }        public async Task<bool> DeleteJuntaDetalleArchivos(int nJuntaDetalleArchivosID)        {            const string sSql = @"                DELETE FROM jnt.JuntaDetalleArchivos                WHERE JuntaDetalleArchivoID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nJuntaDetalleArchivosID });            return vAffected > 0;        }    }}